shellCommands.command:
/bin/bash -lc "cat .gitignore && cat > /tmp/pulse-browser/check.mjs <<'EOF'
import {chromium} from 'playwright';
import assert from 'node:assert/strict';
const browser=await chromium.launch({headless:true,args:['--no-sandbox'],executablePath:'/home/node/.cache/ms-playwright/chromium-1248/chrome-linux-arm64/chrome'});
const page=await browser.newPage({viewport:{width:1440,height:1080},deviceScaleFactor:1});
const errors=[];
page.on('pageerror', e=>errors.push(e.message));
await page.goto('http://localhost:5175/',{waitUntil:'networkidle'});
await page.screenshot({path:'/tmp/pulse-light.png',fullPage:true});
assert.equal(await page.locator('.metric-card').count(),4);
assert.equal(await page.locator('.current-line').count(),1);
assert.equal(await page.locator('.previous-line').count(),1);
await page.getByRole('button',{name:'Тёмная',exact:true}).click();
assert(await page.locator('.app-shell').evaluate(el=>el.classList.contains('dark')));
assert.equal(await page.locator('.current-line').evaluate(el=>getComputedStyle(el).stroke),'rgb(242, 146, 110)');
await page.screenshot({path:'/tmp/pulse-dark.png',fullPage:true});
await page.reload();
assert(await page.locator('.app-shell').evaluate(el=>el.classList.contains('dark')));
await page.getByRole('button',{name:'Системная',exact:true}).click();
await page.emulateMedia({colorScheme:'light'});
await page.waitForFunction(()=>document.querySelector('.app-shell').classList.contains('light'));
await page.emulateMedia({colorScheme:'dark'});
await page.waitForFunction(()=>document.querySelector('.app-shell').classList.contains('dark'));
await page.getByRole('button',{name:'Светлая',exact:true}).click();
await page.locator('.metric-card').nth(2).click();
assert.match(await page.locator('.chart-heading h2').innerText(),/конверсии/);
await page.getByLabel('Сравнить с прошлым периодом').uncheck();
assert.equal(await page.locator('.previous-line').count(),0);
await page.getByLabel('Сравнить с прошлым периодом').check();
await page.getByRole('button',{name:'Неделя',exact:true}).click();
assert.match(await page.getByRole('img').getAttribute('aria-label'),/5 точек/);
await page.getByRole('button',{name:'Месяц',exact:true}).click();
assert.match(await page.getByRole('img').getAttribute('aria-label'),/1 точек/);
await page.locator('.date-button').click();
await page.getByRole('button',{name:'Последние 7 дней',exact:true}).click();
assert.match(await page.locator('.date-button').innerText(),/24–30/);
await page.getByRole('button',{name:'День',exact:true}).click();
assert.match(await page.getByRole('img').getAttribute('aria-label'),/7 точек/);
await page.getByRole('img').focus();
await page.keyboard.press('ArrowRight');
assert.equal(await page.locator('.chart-tooltip').count(),1);
const downloadEvent=page.waitForEvent('download');
await page.getByRole('button',{name:'Экспорт',exact:true}).click();
const download=await downloadEvent;
assert.equal(download.suggestedFilename(),'pulse-conversion-7days.csv');
await page.getByRole('button',{name:'Открыть помощь',exact:true}).click();
assert(await page.locator('dialog').isVisible());
await page.keyboard.press('Escape');
assert("'!(await page.locator('"'dialog').isVisible()));
await page.setViewportSize({width:390,height:844});
await page.locator('.metric-card').first().click();
await page.screenshot({path:'/tmp/pulse-mobile.png',fullPage:true});
assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'mobile page overflows');
await page.getByRole('button',{name:'Тёмная',exact:true}).click();
await page.screenshot({path:'/tmp/pulse-mobile-dark.png',fullPage:true});
assert.deepEqual(errors,[]);
console.log('PASS: chart, themes, persisted preference, system theme, metrics, comparison, aggregation, date presets, keyboard, CSV, help dialog, mobile overflow.');
await browser.close();
EOF
node /tmp/pulse-browser/check.mjs"
